insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 1, 'O SENHOR reina, tremam as nações; [ele é] o que se senta [entre] os querubins, mova-se a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 2, 'O SENHOR é grande em Sião; ele é mais elevado que todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 3, 'Louvem o teu grande e temível nome, [porque] ele é santo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 4, 'Assim como também a fortaleza do Rei, que ama o juízo; tu firmaste as coisas corretas; tu fizeste juízo e justiça em Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 5, 'Exaltai ao SENHOR nosso Deus, e prostrai-vos perante o suporte dos seus pés, [porque] ele é santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 6, 'Moisés e Arão estavam entre seus sacerdotes, e Samuel entre os que chamavam o seu nome; eles clamavam ao SENHOR, e ele os respondia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 7, 'Na coluna da nuvem ele lhes falava; eles guardavam seus testemunhos e os estatutos que ele tinha lhes dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 8, 'Ó SENHOR nosso Deus, tu os respondia; tu lhes foste Deus perdoador, ainda que vingasse as coisas que eles praticavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 99, 9, 'Exaltai ao SENHOR nosso Deus, e prostrai-vos perante seu santo monte; pois santo é o SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 100, 1, 'Salmo de louvor: Gritai de alegria ao SENHOR toda a terra!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 100, 2, 'Servi ao SENHOR com alegria; vinde com alegre canto perante sua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 100, 3, 'Sabei que o SENHOR é Deus; foi ele, e não nós, que nos fez seu povo, e ovelhas de seu pasto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 100, 4, 'Entrai pelas portas dele com agradecimento, por seus pátios com canto de louvor; agradecei a ele, [e] bendizei o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 100, 5, 'Porque o SENHOR é bom, sua bondade [dura] para sempre; e a fidelidade dele [continua] de geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 1, 'Salmo de Davi: Cantarei sobre a bondade e o juízo; a ti, SENHOR, tocarei melodia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 2, 'No caminho correto eu meditarei; [mas] quando virás a mim? Em sinceridade de meu coração andarei dentro de minha casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 3, 'Não porei perante meus olhos obra maligna; odeio as ações dos que desviam, [tais coisas] não me tomarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 4, 'O coração perverso se afastará de mim; não conhecerei ao mau.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 5, 'Destruirei ao que fala mal de seu próximo as escondidas, e não tolerarei ao que tem olhos cobiçosos e coração arrogante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 6, 'Meus olhos [estarão] sobre os fiéis da terra, para que se sentem comigo; aquele que anda no caminho correto, esse me servirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 7, 'Aquele que usa de engano não habitará em minha casa; aquele que fala mentiras não conseguirá ficar firme perante meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 101, 8, 'Pelas madrugadas destruirei a todos os perversos da terra, para tirar da cidade do SENHOR todos os que praticam maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 1, 'Oração do aflito, quando ele se viu desfalecido, e derramou sua súplica diante do SENHOR: Ó SENHOR, ouve minha oração; e que meu clamor chegue a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 2, 'Não escondas de mim o teu rosto no dia da minha angústia; inclina a mim teu ouvidos; no dia em que eu clamar, apressa-te para me responder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 3, 'Porque os meus dias têm se desfeito como fumaça; e meus ossos se têm se queimado como [n] um forno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 4, 'Meu coração, tal como a erva, está tão ferido e seco, que me esqueci de comer meu pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 5, 'Por causa da voz do meu gemido, meus ossos têm se grudado à minha carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 6, 'Estou semelhante a uma ave no deserto, estou como uma coruja num lugar desabitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 7, 'Fico alerta e estou como um pardal solitário sobre o telhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 8, 'Os meus inimigos me insultam o dia todo; os que me odeiam juram [maldições] contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 9, 'Porque estou comendo cinza como [se fosse] pão, e misturo minha bebida com lágrimas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 10, 'Por causa de tua irritação e tua ira; porque tu me levantaste e me derrubaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 11, 'Meus dias [têm sido] como a sombra, que declina; e eu estou secando como a erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 12, 'Porém tu, SENHOR, permaneces para sempre; e tua lembrança [continua] geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 13, 'Tu te levantarás, e terás piedade de Sião; porque chegou o tempo determinado para se apiedar dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 14, 'Pois os teus servos se agradam de suas pedras, e sentem compaixão do pó de suas [ruínas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 15, 'Então as nações temerão o nome do SENHOR; e todos os reis da terra [temerão] a tua glória;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 16, 'Quando o SENHOR edificar a Sião, [e] aparecer em sua glória;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 17, 'E der atenção à oração do desamparado, e não desprezar sua oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 18, 'Isto será escrito para a geração futura; e o povo que for criado louvará ao SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 19, 'Porque ele olhará desde o alto de seu santuário; o SENHOR olhará desde os céus para a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 20, 'Para ouvir o gemido dos prisioneiros; para soltar aos sentenciados à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 21, 'Para eles anunciarem o nome do SENHOR em Sião, e seu louvor em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 22, 'Quando os povos se reunirem, e os reinos, para servirem ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 23, 'Ele abateu minha força no caminho; abreviou os meus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 24, 'Eu dizia: Meu Deus, não me leves no meio dos meus dias; teus anos são [eternos] ,geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 25, 'Desde muito antes fundaste a terra; e os céus são obra de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 26, 'Eles se destruirão, porém tu permanecerás; e todos eles como vestimentas se envelhecerão; como roupas tu os mudarás, e serão mudados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 27, 'Porém tu és o mesmo; e teus anos nunca se acabarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 102, 28, 'Os filhos de teus servos habitarão [seguros] ,e a semente deles será firmada perante ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 1, 'Salmo de Davi: Louva ao SENHOR, ó minha alma; e que todo o meu interior [louve] ao seu santo nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 2, 'Louva ao SENHOR, ó minha alma; e não te esqueças de nenhum dos benefícios dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 3, 'Que perdoa todas as tuas perversidades, e te sara de todas as tuas enfermidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 4, 'Que resgata tua vida da perdição; que te coroa com bondade e misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 5, 'Que farta tua boca de coisas boas, e tua juventude é renovada como a águia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 6, 'O SENHOR faz justiça e juízos a todos os oprimidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 7, 'Ele fez Moisés conhecer seus caminhos, e os filhos de Israel [conhecerem] as obras dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 8, 'Misericordioso e piedoso é o SENHOR, que demora para se irar, e é grande em bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 9, 'Ele não reclamará perpetuamente, nem manterá [sua ira] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 10, 'Ele não nos trata conforme nossos pecados, nem nos retribui conforme nossas perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 11, 'Porque, assim como os céus estão bem mais elevados que a terra, assim também prevalece a bondade dele sobre aqueles que o temem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 12, 'Assim como o oriente está longe do ocidente, assim também ele tira para longe de nós nossas transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 13, 'Assim como um pai se compadece dos filhos, assim também o SENHOR se compadece daqueles que o temem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 14, 'Porque ele sabe como fomos formados; ele se lembra de que somos pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 15, 'Os dias do homem são como a erva, como a flor do campo, assim ele floresce.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 16, 'Mas quando o vento passa por ele, logo perece; e seu lugar deixa de ser conhecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 17, 'Porém a bondade do SENHOR [continua] de eternidade em eternidade sobre os que o temem; e a justiça dele [está] sobre os filhos de [seus] filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 18, 'Sobre os que guardam o seu pacto dele, e sobre os que se lembram de dos mandamentos dele, para os praticarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 19, 'O SENHOR firmou o seu trono nos céus, e seu reino domina sobre tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 20, 'Bendizei ao SENHOR, ó anjos dele; vós, fortes valentes, que guardais sua palavra, ao ouvirem a voz de sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 21, 'Bendizei ao SENHOR todos os seus exércitos; vós que servis a ele, que fazeis o que lhe agrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 103, 22, 'Bendizei ao SENHOR todas as suas obras, em todos os lugares de seu domínio; louva, minha alma, ao SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 1, 'Louva, minha alma, ao SENHOR; ó SENHOR meu Deus, tu és grandioso; de majestade e de glória estás vestido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 2, 'Tu estás coberto de luz, como que uma roupa; estendes os céus como cortinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 3, 'Ele, que fixou seus cômodos sobre as águas; que faz das nuvens sua carruagem; que se move sobre as asas do vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 4, 'Que faz de seus anjos ventos, e de seus servos fogo flamejante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 5, 'Ele fundou a terra sobre suas bases; ela jamais se abalará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 6, 'Com o abismo, como um vestido, tu a cobriste; sobre os montes estavam as águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 7, 'Elas fugiram de tua repreensão; pela voz de teu trovão elas se recolheram apressadamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 8, 'Os montes subiram [e] os vales desceram ao lugar que tu lhes tinha fundado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 9, 'Tu [lhes] puseste um limite, que não ultrapassarão; não voltarão mais a cobrir a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 10, 'Ele envia fontes aos vales, para que corram por entre os montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 11, 'Elas dão de beber a todos os animais do campo; os asnos selvagens matam a sede [com elas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 12, 'Junto a elas habitam as aves dos céus, que dão [sua] voz dentre os ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 13, 'Ele rega os montes desde seus cômodos; a terra se farta do fruto de tuas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 14, 'Ele faz brotar a erva para os animais, e as plantas para o trabalho do homem, fazendo da terra produzir o pão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 15, 'E o vinho, que alegra o coração do homem, [e] faz o rosto brilhar o rosto com o azeite; com o pão, que fortalece o coração do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 16, 'As árvores do SENHOR são fartamente [nutridas] ,os cedros do Líbano, que ele plantou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 17, 'Onde as aves fazem ninhos, e os pinheiros são as casas para as cegonhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 18, 'Os altos montes são para as cabras selvagens; as rochas, refúgio para os coelhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 19, 'Ele fez a lua para [marcar] os tempos, e o sol sobre seu poente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 20, 'Ele dá ordens à escuridão, e faz haver noite, quando saem todos os animais do mato.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 21, 'Os filhos dos leões, rugindo pela presa, e para buscar de Deus sua comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 22, 'Quando o sol volta a brilhar, [logo] se recolhem, e vão se deitar em suas tocas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 23, 'Então o homem sai para seu trabalho e sua obra até o entardecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 24, 'Como são muitas as suas obras, SENHOR! Tu fizeste todas com sabedoria; a terra está cheia de teus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 25, 'Este grande e vasto mar, nele há inúmeros seres, animais pequenos e grandes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 26, 'Por ali andam os navios e o Leviatã que formastes, para que te alegrasses nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 27, 'Todos eles aguardam por ti, que [lhes] dês seu alimento a seu tempo [devido] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 28, 'O que tu dás, eles recolhem; tu abres tua mão, [e] eles se fartam de coisas boas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 29, '[Quando] tu escondes teu rosto, eles ficam perturbados; [quando] tu tiras o fôlego deles, [logo] eles morrem, e voltam ao seu pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 30, 'Tu envias o teu fôlego, e logo são criados; e [assim] tu renovas a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 31, 'A glória do SENHOR será para sempre; alegre-se o SENHOR em suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 32, '[Quando] ele olha para a terra, [logo] ela treme; [quando] ele toca nos montes, eles soltam fumaça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 33, 'Cantarei ao SENHOR em [toda] a minha vida; tocarei música ao meu Deus enquanto eu existir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 34, 'Meus pensamentos lhe serão agradáveis; eu me alegrarei no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 104, 35, 'Os pecadores serão consumidos da terra, e os maus não existirão mais. Bendizei, ó minha alma, ao SENHOR! Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 1, 'Agradecei ao SENHOR, chamai o seu nome; anunciai suas obras entre os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 2, 'Cantai a ele, tocai músicas para ele; falai de todas as suas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 3, 'Tende orgulho de seu santo nome; alegre-se o coração dos que buscam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 4, 'Buscai ao SENHOR e à sua força; buscai a presença dele continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 5, 'Lembrai-vos de suas maravilhas, que ele fez; de seus milagres, e dos juízos de sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 6, 'Vós, [que sois da] semente de seu servo Abraão; vós, filhos de Jacó, seus escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 7, 'Ele é o SENHOR, nosso Deus; seus juízos [estão] em toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 8, 'Ele se lembra para sempre de seu pacto, da palavra que ele mandou até mil gerações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 9, 'O qual ele firmou com Abraão, e de seu juramento a Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 10, 'O qual também confirmou a Jacó como estatuto, a Israel como pacto eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 11, 'Dizendo: A ti darei a terra de Canaã, a porção de vossa herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 12, 'Sendo eles poucos em número; [eram] poucos, e estrangeiros nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 13, 'E andaram de nação em nação, de um reino a outro povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 14, 'Ele não permitiu a ninguém que os oprimisse; e por causa deles repreendeu a reis,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 15, '[Dizendo] : Não toqueis nos meus ungidos, e não façais mal a meus profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 16, 'E chamou a fome sobre a terra; ele interrompeu toda fonte de alimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 17, 'Enviou um homem adiante deles: José, [que] foi vendido como escravo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 18, 'Amarraram seus pés em correntes; ele foi preso com ferros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 19, 'Até o tempo que sua mensagem chegou, a palavra do SENHOR provou o valor que ele tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 20, 'O rei mandou que ele fosse solto; o governante de povos o libertou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 21, 'Ele o pôs como senhor de sua casa, e por chefe de todos os seus bens,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 22, 'Para dar ordens a suas autoridades, e instruir a seus anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 23, 'Então Israel entrou no Egito; Jacó peregrinou na terra de Cam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 24, 'E fez seu povo crescer muito, e o fez mais poderoso que seus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 25, 'E mudou o coração [dos outros] ,para que odiassem ao seu povo, para que tratassem mal a seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 26, '[Então] enviou seu servo Moisés, e a Arão, a quem tinha escolhido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 27, '[Que] fizeram entre eles os sinais anunciados, e coisas sobrenaturais na terra de Cam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 28, 'Ele mandou trevas, e fez escurecer; e não foram rebeldes a sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 29, 'Ele transformou suas águas em sangue, e matou a seus peixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 30, 'A terra deles produziu rãs em abundância, [até] nos quartos de seus reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 31, 'Ele falou, e vieram vários bichos [e] piolhos em todos os seus limites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 32, 'Tornou suas chuvas em saraiva; [pôs] fogo ardente em sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 33, 'E feriu suas vinhas e seus figueirais; e quebrou as árvores de seus territórios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 34, 'Ele falou, e vieram gafanhotos, e incontáveis pulgões;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 35, 'E comeram toda a erva de sua terra; e devoraram o fruto de seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 36, 'Também feriu a todos os primogênitos em sua terra; os primeiros de todas as suas forças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 37, 'E os tirou [dali] com prata e ouro; e dentre suas tribos não houve quem tropeçasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 38, '[Até] o Egito se alegrou com a saída deles, porque seu temor tinha caído sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 39, 'Ele estendeu uma nuvem como cobertor, e um fogo para iluminar a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 40, 'Eles pediram, e fez vir codornizes; e os fartou com pão do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 41, 'Ele abriu uma rocha, e dela saíram águas; [e] correram [como] um rio pelos lugares secos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 42, 'Porque se lembrou de sua santa palavra, e de seu servo Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 43, 'Então ele tirou [dali] a seu povo com alegria; e seus eleitos com celebração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 44, 'E lhes deu as terras das nações; e do trabalho das nações tomaram posse;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 105, 45, 'Para que guardassem seus estatutos, e obedecessem a leis dele. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 1, 'Aleluia! Agradecei ao SENHOR, porque ele é bom, porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 2, 'Quem falará das proezas do SENHOR? [Quem] dirá louvores a ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 3, 'Bem-aventurados [são] os que guardam o juízo; [e] aquele que pratica justiça em todo tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 4, 'Lembra-te de mim, SENHOR, conforme [tua] boa vontade [para com] teu povo; concede-me tua salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 5, 'Para eu ver o bem de teus escolhidos; para eu me alegrar com a alegria de teu povo; para eu ter orgulho de tua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 6, 'Pecamos com nossos pais, fizemos o mal, agimos perversamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 7, 'Nossos pais no Egito não deram atenção a tuas maravilhas, nem se lembraram da abundância de tuas bondades; mas ao invés disso se rebelaram junto ao mar, perto do mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 8, 'Apesar disso ele os livrou por causa de seu nome, para que seu poder fosse conhecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 9, 'E repreendeu ao mar Vermelho, e [este] se secou; e os fez caminharem pelas profundezas [do mar] ,como que pelo deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 10, 'E os livrou das mãos daquele que os odiava, e os resgatou das mãos do inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 11, 'E as águas cobriram seus adversários; não sobrou nem um sequer deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 12, 'Então creram nas palavras dele, e cantaram louvores a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 13, '[Porém] logo se esqueceram das obras dele, e não esperaram pelo seu conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 14, 'Mas foram levados pelo mau desejo no deserto, e tentaram a Deus no lugar desabitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 15, 'Então ele lhes concedeu o que pediam, porém enviou magreza a suas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 16, 'E tiveram inveja de Moisés no acampamento; [e] de Arão, o santo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 17, 'A terra se abriu, e engoliu a Datã; e encobriu ao grupo de Abirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 18, 'E o fogo consumiu o seu grupo; a chama queimou os perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 19, 'Fizeram um bezerro em Horebe; e se inclinaram perante uma imagem de fundição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 20, 'E mudaram sua glória na figura de um boi, que come erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 21, 'Esqueceram-se de Deus, o salvador deles, que tinha feito coisas grandiosas no Egito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 22, 'Maravilhas na terra de Cam, coisas temíveis no mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 23, 'Por isso ele disse que teria os destruído, se Moisés, seu escolhido, não tivesse se posto na fenda diante dele, para desviar sua ira, para não os destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 24, 'Eles também desprezaram a terra desejável, [e] não creram na palavra dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 25, 'E ao invés disso murmuraram em suas tendas, [e] não deram ouvidos à voz do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 26, 'Por isso ele levantou sua mão contra eles, [jurando] que os derrubaria no deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 27, 'E que derrubaria sua semente entre as nações; e os dispersaria pelas terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 28, 'Eles também passaram a adorar Baal-Peor, e a comer sacrifícios dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 29, 'E o provocaram à ira com as obras deles; e [por isso] surgiu a praga entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 30, 'Então se levantou Fineias, e interveio, e cessou aquela praga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 31, 'E isto lhe foi reconhecido como justiça, de geração em geração, para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 32, 'Também o irritaram muito junto às águas de Meribá; e houve mal a Moisés por causa deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 33, 'Porque provocaram o seu espírito, de modo que ele falou imprudentemente com seus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 34, 'Eles não destruíram os povos que o SENHOR tinha lhes mandado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 35, 'Mas ao invés disso, se misturaram com as nações, e aprenderam as obras delas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 36, 'E serviram a seus ídolos; e vieram a lhes ser por laço de armadilha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 37, 'Além disso, sacrificaram seus filhos e suas filhas a demônios,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 38, 'E derramaram sangue inocente, o sangue de seus filhos e de suas filhas, os quais eles sacrificaram aos ídolos de Canaã; e a terra foi profanada com [este] sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 39, 'E contaminaram-se com suas obras; e se prostituíram com suas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 40, 'Por isso a ira do SENHOR se acendeu contra seu povo; e ele odiou sua propriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 41, 'E os entregou nas mãos das nações estrangeiras, e aqueles que os odiavam passaram a dominá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 42, 'E seus inimigos os oprimiram, e foram humilhados sob as mãos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 43, 'Muitas vezes ele os livrou; mas eles [voltavam a] irritá-lo com seus pensamentos, e foram abatidos pela sua perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 44, 'Apesar disso, ele observou a angústia deles, e ouviu quando eles clamaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 45, 'E ele se lembrou de seu pacto em [favor] deles, e sentiu pena conforme suas muitas bondades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 46, 'E fez com que todos os que os mantinham em cativeiro tivessem misericórdia deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 47, 'Salva-nos, SENHOR nosso Deus, e ajunta-nos dentre as nações, para darmos graças ao teu santo nome, e termos orgulho em louvar a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 106, 48, 'Bendito [seja] o SENHOR, Deus de Israel, desde sempre e para sempre! E todo o povo diga Amém! Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 1, 'Agradecei ao SENHOR, porque ele é bom; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 2, 'Digam [isso] os resgatados pelo SENHOR, os quais ele resgatou das mão do adversário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 3, 'E os que ele ajuntou de todas as terras, do oriente e do ocidente, do norte e do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 4, 'Os que andaram sem rumo no deserto, por caminhos solitários; os que não acharam cidade para morarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 5, 'Famintos e sedentos, suas almas neles desfaleciam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 6, 'Mas eles clamaram ao SENHOR em suas angústias, e ele os livrou de suas aflições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 7, 'E os levou ao caminho correto, para irem a uma cidade de moradia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 8, 'Agradeçam ao SENHOR por sua bondade, e suas maravilhas perante os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 9, 'Porque ele fartou a alma sedenta, e encheu de bem a alma faminta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 10, 'Os que estavam sentados em trevas e sombra de morte, presos com aflição e ferro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 11, 'Porque se rebelaram contra os mandamentos de Deus, e rejeitaram o conselho do Altíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 12, 'Por isso ele abateu seus corações com trabalhos cansativos; eles tropeçaram, e não houve quem os socorresse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 13, 'Porém eles clamaram ao SENHOR em suas angústias, e ele os livrou de suas aflições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 14, 'Ele os tirou das trevas e da sombra da morte, e quebrou suas correntes de prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 15, 'Agradeçam ao SENHOR pela sua bondade, e suas maravilhas perante os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 16, 'Porque ele quebrou as portas de bronze, e despedaçou os ferrolhos de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 17, 'Os tolos foram afligidos por causa de seu caminho de transgressões e por suas perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 18, 'A alma deles perdeu o interesse por todo tipo de comida, e chegaram até às portas da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 19, 'Porém eles clamaram ao SENHOR em suas angústias, e ele os livrou de suas aflições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 20, 'Ele enviou sua palavra, e os sarou; e ele os livrou de suas covas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 21, 'Agradeçam ao SENHOR por sua bondade, e suas maravilhas perante os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 22, 'E sacrifiquem sacrifícios de gratidão; e anunciai as obras dele com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 23, 'Os que descem ao mar em navios, trabalhando em muitas águas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 24, 'Esses veem as obras do SENHOR, e suas maravilhas nas profundezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 25, '[Porque] quando ele fala, ele faz levantar tormentas de vento, que levanta suas ondas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 26, 'Elas sobem aos céus, [e] descem aos abismos; a alma deles se derrete de angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 27, 'Eles cambaleiam e vacilam como bêbados, e toda a sabedoria deles se acaba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 28, 'Então eles clamaram ao SENHOR em suas angústias, e ele os tirou de suas aflições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 29, 'Ele fez cessar as tormentas, e as ondas se calaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 30, 'Então se alegraram, porque houve calmaria; e ele os levou ao porto que queriam [chegar] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 31, 'Agradeçam ao SENHOR por sua bondade, e suas maravilhas perante os filhos dos homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 32, 'E exaltem a ele na assembleia do povo, e o glorifiquem na reunião dos anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 33, 'Ele torna os rios em deserto, e as saídas de águas em terra seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 34, 'A terra frutífera em salgada, pela maldade dos que nela habitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 35, 'Ele torna o deserto em lagoa, e a terra seca em nascentes de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 36, 'E faz aos famintos habitarem ali; e eles edificam uma cidade para morarem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 37, 'E semeiam campos, e plantam vinhas, que produzem fruto valioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 38, 'E ele os abençoa, e se multiplicam muito, e o gado dele não diminui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 39, 'Mas [quando] eles se diminuem e se abatem, por causa da opressão, mal e aflição;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 40, 'Ele derrama desprezo sobre os governantes, e os faz andar sem rumo pelos desertos, sem [terem] caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 41, 'Mas ao necessitado, ele levanta da opressão a um alto retiro, e faz famílias como a rebanhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 42, 'Os corretos, ao verem, ficam alegres, e todo perverso se calará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 107, 43, 'Quem é sábio, que preste atenção a estas coisas, e reflita nas bondades do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 1, 'Cântico e Salmo de Davi: Preparado está meu coração, ó Deus; cantarei e tocarei música [com] minha glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 2, 'Desperta-te, lira e harpa; eu despertarei ao amanhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 3, 'Louvarei a ti entre os povos, SENHOR, e tocarei música a ti entre as nações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 4, 'Porque tua bondade é maior que os céus, e tua fidelidade mais alta que as nuvens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 5, 'Exalta-te sobre os céus, ó Deus; e tua glória sobre toda a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 6, 'Para que teus amados sejam libertados; salva [-nos] com tua mão direita, e responde-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 7, 'Deus falou em seu santuário: Eu me alegrarei; repartirei a Siquém, e medirei ao vale de Sucote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 8, 'Meu é Gileade, meu é Manassés; e Efraim é a fortaleza de minha cabeça; Judá é meu legislador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 9, 'Moabe é minha bacia de lavar; sobre Edom lançarei meu sapato; sobre a Filístia eu triunfarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 10, 'Quem me levará a uma cidade fortificada? Quem me guiará até Edom?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 11, 'Por acaso não serás tu, ó Deus? Tu que tinha nos rejeitado, e não saías [mais] com nossos exércitos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 12, 'Dá-nos ajuda [para livrarmos] da angústia, porque o socorro humano é inútil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 108, 13, 'Em Deus faremos proezas; e ele pisoteará nossos adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 1, 'Salmo de Davi, para o regente: Ó Deus a quem eu louvo, não fiques calado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 2, 'Porque a boca do perverso, e a boca enganadora já se abriram contra mim; falaram de mim com língua falsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 3, 'E me cercaram com palavras de ódio; e lutaram contra mim sem motivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 4, 'Fizeram-se contra mim por causa de meu amor; porém eu [me mantenho] em oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 5, 'Retribuíram o bem com o mal, e o meu amor com ódio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 6, 'Põe algum perverso contra ele, e que haja um acusador à sua direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 7, 'Quando for julgado, que saia condenado; e que a oração dele seja [considerada] como pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 8, 'Sejam os dias dele poucos, e que outro tome sua atividade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 9, 'Sejam seus filhos órfãos, e sua mulher seja viúva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 10, 'E que seus filhos andem sem rumo, e mendiguem; e busquem [para si longe] de suas ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 11, 'Que o credor tome tudo o que ele tem, e estranhos saqueiem seu trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 12, 'Haja ninguém que tenha piedade dele, e haja ninguém que se compadeça de seus órfãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 13, 'Sejam seus descendentes cortados de vez; [e] que o nome deles seja apagado da geração seguinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 14, 'Que a perversidade de seus pais seja lembrada pelo SENHOR, e que o pecado de sua mãe não seja apagado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 15, '[Porém que tais coisas] estejam sempre perante o SENHOR, e corte-se a lembrança deles da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 16, 'Porque ele não se lembrou de fazer o bem; ao invés disso, perseguiu ao homem humilde e necessitado, e ao de coração quebrado, para [o] matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 17, 'Já que ele amou a maldição, então que ela lhe sobrevenha; e já que ele não quis a bênção, que esta se afaste dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 18, 'E ele seja revestido de maldição, como se lhe fosse sua roupa, como água dentro do seu corpo, e como óleo em seus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 19, 'Que ela seja como uma roupa com que ele se cubra, e como cinto com que ele sempre põe ao seu redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 20, 'Isto seja o pagamento do SENHOR para os meus adversários, e para os que falam mal contra minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 21, 'Porém tu, Senhor DEUS, me trata [bem] por causa do teu nome; por ser boa a tua misericórdia, livra-me;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 22, 'Porque estou aflito e necessitado; e meu coração está ferido dentro de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 23, 'Eu vou como a sombra, que declina; estou sendo sacudido como um gafanhoto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 24, 'Meus joelhos estão fracos de [tanto] jejuar; minha carne está magra, sem gordura alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 25, 'E eu por eles sou humilhado; quando me veem, sacodem suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 26, 'Socorre-me, SENHOR Deus meu; salva-me conforme a tua bondade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 27, 'Para que saibam que esta é a tua mão; e que assim tu a fizeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 28, 'Maldigam eles, mas bendize tu; levantem-se eles, mas sejam envergonhados; e o teu servo se alegre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 29, 'Que meus adversários se vistam de vergonha, e cubram-se com sua própria humilhação, como [se fosse] uma capa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 30, 'Agradecerei grandemente ao SENHOR com minha boca, e no meio de muitos eu o louvarei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 109, 31, 'Porque ele se põe à direita do necessitado, para [o] livrar daqueles que atacam a sua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 1, 'Salmo de Davi: O SENHOR disse a meu Senhor: Senta-te à minha direita, até que eu ponha teus inimigos por escabelo de teus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 2, 'O SENHOR enviará o cetro de tua força desde Sião, [dizendo] : Domina tu no meio de teus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 3, 'Teu povo será voluntário no dia do teu poder; com santas honras, desde o ventre do amanhecer, tu [terás] o orvalho de tua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 4, 'O SENHOR jurou, e não se arrependerá: Tu és Sacerdote eterno, segundo a ordem de Melquisedeque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 5, 'O Senhor está à tua direita; ele ferirá aos reis no dia de sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 6, 'Julgará entre as nações; ele [as] encherá de corpos mortos; [e] ferirá a cabeça de uma grande terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 110, 7, 'Ele beberá do ribeiro no caminho, então levantará a cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 1, 'Aleluia! Louvarei ao SENHOR com todo o coração, no conselho e na congregação dos corretos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 2, 'Grandes são as obras do SENHOR; procuradas por todos os que nelas se agradam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 3, 'Glória e majestade são o seu agir, e sua justiça permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 4, 'Ele fez memoráveis as suas maravilhas; piedoso é misericordioso é o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 5, 'Ele deu alimento aos que o temem; ele se lembrará para sempre de seu pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 6, 'Ele anunciou o poder se suas obras a seu povo, dando-lhes a herança de nações [estrangeiras] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 7, 'As obras de suas mãos são verdade e juízo, e todos os seus mandamentos são fiéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 8, 'Eles ficarão firmes para sempre, e são feitos em verdade e justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 9, 'Ele enviou resgate a seu povo, ordenou seu pacto para sempre; santo e temível é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 111, 10, 'O temor ao SENHOR é o princípio da sabedoria; inteligentes são todos o que isto praticam. O louvor a ele dura para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 1, 'Aleluia! Bem-aventurado é o homem que teme ao SENHOR, e que tem muito prazer em seus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 2, 'Sua descendência será poderosa na terra; a geração dos corretos será bendita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 3, 'Em sua casa [haverá] bens e riquezas, e sua justiça permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 4, 'A luz brilha nas trevas para os corretos, [para quem é] piedoso, misericordioso e justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 5, 'O homem bom é misericordioso, e empresta; ele administra suas coisas com prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 6, 'Certamente ele nunca se abalará; o justo será lembrado para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 7, 'Ele não temerá o mau rumor; o seu coração está firme, confiante no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 8, 'Seu firme coração não temerá, até que ele veja [o fim] de seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 9, 'Ele distribui, e dá aos necessitados; sua justiça permanece para sempre; seu poder será exaltado em glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 112, 10, 'O perverso verá, e ficará incomodado; rangerá seus dentes, e se consumirá. O desejo dos perversos perecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 1, 'Aleluia! Louvai, vós servos do SENHOR, louvai o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 2, 'Seja o nome do SENHOR bendito, desde agora para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 3, 'Desde o nascer do sol até o poente, seja louvado o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 4, 'O SENHOR está elevado acima de todas as nações; [e] sua glória acima dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 5, 'Quem é como o SENHOR nosso Deus? Ele que habita nas alturas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 6, 'Que se abaixa para ver [o que há] nos céus e na terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 7, 'Que do levanta o pobre do pó da terra, e levanta o necessitado da sujeira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 8, 'Para fazê-lo sentar com os príncipes, com os príncipes de seu povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 113, 9, 'Que faz a estéril habitar em família, como alegre mãe de filhos. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 1, 'Quando Israel saiu do Egito, [quando] a casa de Jacó [saiu] de um povo estrangeiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 2, 'Judá se tornou seu santuário, [e] Israel os seus domínios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 3, 'O mar viu, e fugiu; e o Jordão recuou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 4, 'Os montes saltaram como carneiros, os morros como cordeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 5, 'O que houve, ó mar, que fugiste? Ó Jordão, que recuaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 6, 'Ó montes, que saltastes como carneiros? Ó morros, como cordeiros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 7, 'Trema tu, ó terra, pela presença do Senhor, pela presença do Deus de Jacó,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 114, 8, 'Que tornou a rocha em lago de águas; ao pedregulho em fonte de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 1, 'Não a nós, SENHOR; não a nós, mas a teu nome dá glória; por tua bondade, por tua fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 2, 'Porque as nações dirão: Onde está o Deus deles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 3, 'Porém nosso Deus está nos céus, ele faz tudo o que lhe agrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 4, 'Os ídolos deles são prata e ouro, obras de mãos humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 5, 'Têm boca, mas não falam; têm olhos, mas não veem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 6, 'Têm ouvidos, mas não ouvem; tem nariz, mas não cheiram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 7, 'Têm mãos, mas não apalpam; têm pés, mas não andam; nem falam com suas gargantas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 8, 'Tornem-se como eles os que os fazem, [e] todos os que neles confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 9, 'Ó Israel, confia no SENHOR; ele é sua ajuda e seu escudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 10, 'Ó casa de Arão, confiai no SENHOR; ele é sua ajuda e seu escudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 11, 'Vós que temeis ao SENHOR, confiai no SENHOR; ele é sua ajuda e seu escudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 12, 'O SENHOR tem se lembrado de nós; ele há de abençoar; ele abençoará a casa de Israel; ele abençoará a casa de Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 13, 'Ele abençoará aos que temem ao SENHOR; tanto os pequenos como os grandes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 14, 'O SENHOR vos aumentará, vós e vossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 15, 'Benditos sois vós [que pertenceis] ao SENHOR, que fez os céus e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 16, '[Quanto] aos céus, os céus são do SENHOR; mas a terra ele deu aos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 17, 'Os mortos não louvam ao SENHOR, nem os que descem ao silêncio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 115, 18, 'Porém nós bendiremos ao SENHOR, desde agora e para sempre. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 1, 'Amo o SENHOR, porque ele escuta minha voz [e] minhas súplicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 2, 'Porque ele tem inclinado a mim seus ouvidos; por isso eu clamarei a ele em [todos] os meus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 3, 'Cordas da morte me cercaram, e angústias do Xeol me afrontaram; encontrei opressão e aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 4, 'Mas clamei ao nome do SENHOR, [dizendo] : Ah SENHOR, livra minha alma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 5, 'O SENHOR é piedoso e justo; e nosso Deus é misericordioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 6, 'O SENHOR protege os simples; eu estava com graves problemas, mas ele me livrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 7, 'Minha alma, volta ao teu descanso, pois o SENHOR tem te tratado bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 8, 'Porque tu, [SENHOR] ,livraste minha alma da morte, meus olhos das lágrimas, e meu pé do tropeço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 9, 'Andarei diante do SENHOR na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 10, 'Eu cri, por isso falei; estive muito aflito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 11, 'Eu dizia em minha pressa: Todo homem é mentiroso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 12, 'O que pagarei ao SENHOR por todos os benefícios dele para mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 13, 'Tomarei o copo da salvação, [e] chamarei o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 14, 'Certamente pagarei meus votos ao SENHOR, na presença de todo o seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 15, 'Preciosa é aos olhos do SENHOR a morte de seus santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 16, 'Ah SENHOR, verdadeiramente eu sou teu servo; sou teu servo, filho de tua serva; tu me soltaste das correntes que me prendiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 17, 'Sacrificarei a ti sacrifício de agradecimento, e chamarei o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 18, 'Certamente pagarei meus votos ao SENHOR, na presença de todo o seu povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 116, 19, 'Nos pátios da casa do SENHOR, em meio de ti, ó Jerusalém. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 117, 1, 'Louvai ao SENHOR, todas as nações; celebrai a ele, todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 117, 2, 'Porque sua bondade prevaleceu sobre nós, e a fidelidade do SENHOR [dura] para sempre. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 1, 'Agradecei ao SENHOR, porque ele é bom; pois sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 2, 'Diga agora Israel, que sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 3, 'Diga agora casa de Arão, que sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 4, 'Digam agora os que temem ao SENHOR, que sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 5, 'Na angústia clamei ao SENHOR; [e] o SENHOR me respondeu, e [me pôs] num lugar amplo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 6, 'O SENHOR está comigo, não temerei; o que poderá me fazer o homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 7, 'O SENHOR está comigo entre os que ajudam; por isso verei [o fim] daqueles que me odeiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 8, 'Melhor é buscar refúgio no SENHOR do que confiar no homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 9, 'Melhor é buscar refúgio no SENHOR do que confiar em príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 10, 'Todas as nações me cercaram; [mas foi] no nome do SENHOR que eu as despedacei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 11, 'Cercaram-me, cercaram-me mesmo; [mas foi] no nome do SENHOR que eu as despedacei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 12, 'Cercaram-me como abelhas, mas se apagaram como fogo de espinhos; [porque] foi no nome do SENHOR que eu as despedacei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 13, 'Com força me empurraste para que eu caísse; mas o SENHOR me ajudou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 14, 'O SENHOR é minha força e [minha] canção, porque ele tem sido minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 15, 'Nas tendas dos justos há voz de alegria e salvação; a mão direita do SENHOR faz proezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 16, 'A mão direita do SENHOR se levanta; a mão direita do SENHOR faz proezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 17, 'Eu não morrerei, mas viverei; e contarei as obras do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 18, 'É verdade que o SENHOR me castigou, porém ele não me entregou à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 19, 'Abri para mim as portas da justiça; entrarei por elas [e] louvarei ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 20, 'Esta é a porta do SENHOR, pela qual os justos entrarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 21, 'Eu te louvarei porque tu me respondeste e me salvaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 22, 'A pedra que os construtores rejeitaram se tornou cabeça de esquina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 23, 'Pelo SENHOR isto foi feito, [e] é maravilhoso aos nossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 24, 'Este é o dia em que o SENHOR agiu; alegremos e enchamos de alegria nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 25, 'Ah, SENHOR, salva-nos! Ah, SENHOR, faze [-nos] prosperar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 26, 'Bendito aquele que vem no nome do SENHOR; nós vos bendizemos desde a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 27, 'O SENHOR é o [verdadeiro] Deus, que nos deu luz; atai os [sacrifícios] da festa, para [levá-los] aos chifres do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 28, 'Tu és meu Deus, por isso eu te louvarei. Eu te exaltarei, meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 118, 29, 'Agradecei ao SENHOR, porque ele é bom; pois sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 1, '[Álefe] :Bem-aventurados são os puros em [seus] caminhos, os que andam na lei do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 2, 'Bem-aventurados são os que guardam os testemunhos dele, [e] o buscam com todo o coração;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 3, 'E não praticam perversidade, [mas] andam nos caminhos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 4, 'Tu mandaste que teus mandamentos fossem cuidadosamente obedecidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 5, 'Ah! Como gostaria que meus caminhos fossem dirigidos a guardar teus estatutos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 6, 'Então não me envergonharia, quando eu observasse todos os teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 7, 'Louvarei a ti com um coração correto, enquanto aprendo os juízos de tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 8, 'Eu guardarei teus estatutos; não me abandones por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 9, '[Bete] : Com que um rapaz purificará o seu caminho? Sendo obediente conforme a tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 10, 'Eu te busco como todo o meu coração; não me deixes desviar de teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 11, 'Guardei a tua palavra em meu coração, para eu não pecar contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 12, 'Bendito [és] tu, SENHOR; ensina-me os teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 13, 'Com meus lábios contei todos os juízos de tua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 14, 'Eu me alegro mais com o caminho de teus estatutos, do que com todas as riquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 15, 'Meditarei em teus mandamentos, e darei atenção aos teus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 16, 'Terei prazer em teus estatutos; não me esquecerei de tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 17, '[Guímel] :Trata bem o teu servo, [para] que eu viva, e obedeça tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 18, 'Abre meus olhos, para que eu veja as maravilhas de tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 19, 'Eu sou peregrino na terra, não escondas de mim os teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 20, 'Minha alma está despedaçada de tanto desejar os teus juízos em todo tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 21, 'Tu repreendes aos malditos arrogantes, que se desviam de teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 22, 'Tira-me de minha humilhação e desprezo, pois eu guardei teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 23, 'Até mesmo os príncipes se sentaram, e falaram contra mim; porém o teu servo estava meditando em teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 24, 'Pois teus testemunhos são meus prazeres [e] meus conselheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 25, '[Dálete] :Minha alma está grudada ao pó; vivifica-me conforme tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 26, 'Eu [te] contei os meus caminhos, e tu me respondeste; ensina-me conforme teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 27, 'Faze-me entender o caminho de teus preceitos, para eu falar de tuas maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 28, 'Minha alma se derrama de tristeza; levanta-me conforme tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 29, 'Desvia de mim o caminho de falsidade; e sê piedoso dando-me tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 30, 'Eu escolhi o caminho da fidelidade; e pus [diante de mim] os teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 31, 'Estou apegado a teus testemunhos; ó SENHOR, não me envergonhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 32, 'Correrei pelo caminho de teus mandamentos, porque tu alargaste o meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 33, '[Hê] :Ensina-me, SENHOR, o caminho de teus estatutos, e eu o guardarei até o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 34, 'Dá-me entendimento, e eu guardarei a tua lei, e a obedecerei de todo [o meu] coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 35, 'Faze-me andar na trilha de teus mandamentos, porque nela tenho prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 36, 'Inclina meu coração a teus testemunhos, e não à ganância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 37, 'Desvia meus olhos para que não olhem para coisas inúteis; vivifica-me pelo teu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 38, 'Confirma tua promessa a teu servo, que tem temor a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 39, 'Desvia de mim a humilhação que eu tenho medo, pois teus juízos são bons.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 40, 'Eis que amo os teus mandamentos; vivifica-me por tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 41, '[Vau] :E venham sobre mim tuas bondades, SENHOR; [e também] a tua salvação, segundo tua promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 42, 'Para que eu tenha resposta ao que me insulta; pois eu confio em tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 43, 'E nunca tires de minha boca a palavra da verdade, pois eu espero em teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 44, 'Assim obedecerei a tua lei continuamente, para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 45, 'E andarei [livremente] por longas distâncias, pois busquei teus preceitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 46, 'Também falarei de teus testemunhos perante reis, e não me envergonharei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 47, 'E terei prazer em teus mandamentos, que eu amo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 48, 'E levantarei as minhas mãos a teus mandamentos, que eu amo; e meditarei em teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 49, '[Záin] :Lembra-te da palavra [dada] a teu servo, à qual mantenho esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 50, 'Isto é meu consolo na minha aflição, porque tua promessa me vivifica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 51, 'Os arrogantes têm zombado de mim demasiadamente; [porém] não me desviei de tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 52, 'Eu me lembrei de teus juízos muito antigos, SENHOR; e [assim] me consolei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 53, 'Eu me enchi de ira por causa dos perversos, que abandonam tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 54, 'Teus estatutos foram meus cânticos no lugar de minhas peregrinações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 55, 'De noite tenho me lembrado de teu nome, SENHOR; e tenho guardado tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 56, 'Isto eu tenho feito, porque guardo teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 57, '[Hete] :O SENHOR é minha porção; eu disse que guardaria tuas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 58, 'Busquei a tua face com todo o [meu] coração; tem piedade de mim segundo tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 59, 'Eu dei atenção a meus caminhos, e dirigi meus pés a teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 60, 'Eu me apressei, e não demorei a guardar os teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 61, 'Bandos de perversos me roubaram; [porém] não me esqueci de tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 62, 'No meio da noite eu me levanto para te louvar, por causa dos juízos de tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 63, 'Sou companheiro de todos os que te temem, e dos que guardam os teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 64, 'A terra está cheia de tua bondade, SENHOR; ensina-me os teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 65, '[Tete] :Tu fizeste bem a teu servo, SENHOR, conforme tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 66, 'Ensina-me bom senso e conhecimento, pois tenho crido em teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 67, 'Antes de ter sido afligido, eu andava errado; mas agora guardo tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 68, 'Tu és bom, e fazes o bem; ensina-me os teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 69, 'Os arrogantes forjaram mentiras contra mim; [mas] eu com todo o [meu] coração guardo os teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 70, 'O coração deles se incha como gordura; [mas] eu tenho prazer em tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 71, 'Foi bom pra mim ter sido afligido, para assim eu aprender os teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 72, 'Melhor para mim é a lei de tua boca, do que milhares de [peças] de ouro ou prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 73, '[Iode] :Tuas mãos me fizeram e me formaram; faze-me ter entendimento, para que eu aprenda teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 74, 'Os que te temem olham para mim e se alegram, porque eu mantive esperança em tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 75, 'Eu sei, SENHOR, que teus juízos são justos; e que tu me afligiste [por] tua fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 76, 'Seja agora tua bondade para me consolar, segundo a promessa [que fizeste] a teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 77, 'Venham tuas misericórdias sobre mim, para que eu viva; pois tua lei é o meu prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 78, 'Sejam envergonhados os arrogantes, porque eles me prejudicaram com mentiras; [porém] eu medito em teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 79, 'Virem-se a mim os que te temem e conhecem os teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 80, 'Seja meu coração correto em teus estatutos, para eu não ser envergonhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 81, '[Cafe] :Minha alma desfalece por tua salvação; em tua palavra mantenho esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 82, 'Meus olhos desfaleceram por tua promessa, enquanto eu dizia: Quando tu me consolarás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 83, 'Porque fiquei como um odre na fumaça, [porém] não me esqueci teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 84, 'Quantos serão os dias de teu servo? Quando farás julgamento aos meus perseguidores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 85, 'Os arrogantes me cavaram covas, aqueles que não são conforme a tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 86, 'Todos os teus mandamentos são verdade; com mentiras me perseguem; ajuda-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 87, 'Estou quase que destruído por completo sobre a terra; porém eu não deixei teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 88, 'Vivifica-me conforme tua bondade, então guardarei o testemunho de tua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 89, '[Lâmede] :Para sempre, SENHOR, tua palavra permanece nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 90, 'Tua fidelidade [dura] de geração em geração; tu firmaste a terra, e [assim] ela permanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 91, 'Elas continuam por tuas ordens até hoje, porque todos são teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 92, 'Se a tua lei não fosse meu prazer, eu já teria perecido em minha aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 93, 'Nunca esquecerei de teus mandamentos, porque tu me vivificaste por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 94, 'Eu sou teu, salva-me, porque busquei teus preceitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 95, 'Os perversos me esperaram, para me destruírem; [porém] eu dou atenção a teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 96, 'A toda perfeição eu vi fim; [mas] teu mandamento é extremamente grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 97, '[Mem] :Ah, como eu amo a tua lei! O dia todo eu medito nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 98, 'Ela me faz mais sábio do que meus inimigos [por meio de] teus mandamentos, porque ela está sempre comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 99, 'Sou mais inteligente que todos os meus instrutores, porque medito em teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 100, 'Sou mais prudente que os anciãos, porque guardei teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 101, 'Afastei meus pés de todo mau caminho, para guardar tua palavra.')
